60	/**
61	 * Middleware to set proper MIME types for JavaScript files.
62	 * This is necessary because some browsers (especially Arc) enforce strict MIME type checking
63	 * and will refuse to execute scripts with incorrect MIME types for security reasons.
64	 */
65	export function setJavaScriptMimeType(
66	  req: Request,
67	  res: Response,
68	  next: express.NextFunction,
69	): void {
70	  const ext = path.extname(req.path);
71	  if (JS_EXTENSIONS.has(ext)) {
72	    res.setHeader('Content-Type', 'application/javascript');
73	  }
74	  next();
75	}
