80	export function handleServerError(error: NodeJS.ErrnoException, port: number): void {
81	  if (error.code === 'EADDRINUSE') {
82	    logger.error(`Port ${port} is already in use. Do you have another Promptfoo instance running?`);
83	  } else {
84	    logger.error(`Failed to start server: ${error instanceof Error ? error.message : error}`);
85	  }
86	  process.exit(1);
87	}
