111	  private recordTelemetryDisabled() {
112	    if (!this.telemetryDisabledRecorded) {
113	      this.sendEvent('feature_used', { feature: 'telemetry disabled' });
114	      this.telemetryDisabledRecorded = true;
115	    }
116	  }
117	
118	  record(eventName: TelemetryEventTypes, properties: EventProperties): void {
119	    if (this.disabled) {
120	      this.recordTelemetryDisabled();
121	    } else {
122	      this.sendEvent(eventName, properties);
123	    }
