export const TelemetryEventSchema = z.object({
  event: z.enum([
    'assertion_used',
    'command_used',
    'eval setup',
    'eval_ran',
    'feature_used',
    'funnel',
    'redteam discover',
    'redteam generate',
    'redteam init',
    'redteam poison',
    'redteam report',
